#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate docs/DSL.md from the tool schema in src/maris3d/dsl/tools.py, so the reference cannot drift from the code.

    python3 scripts/gen_dsl_doc.py           # write docs/DSL.md
    python3 scripts/gen_dsl_doc.py --check   # exit 1 if docs/DSL.md is stale
"""
import json, os, sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
sys.path.insert(0, os.path.join(ROOT, "src"))
from maris3d.dsl import tools as T  # noqa: E402

HEAD = """# Tool DSL reference

<!-- GENERATED by scripts/gen_dsl_doc.py from src/maris3d/dsl/tools.py. Do not edit by hand. -->

These are the native tool calls the app runs in Blender. Since 0.2 the model does not write them: it answers in words and the app's
compiler writes the calls. A host model can send them itself through the MCP tool `run_calls`.
A batch is ONE JSON object: `{"calls":[ {...}, {...} ]}`. Each call has a `"tool"` name and that tool's arguments.
At most %d calls per batch (`maxItems` of the schema). `maris3d.dsl.tools.compile_calls(doc)` turns the document into a Blender Python script
(Blender 5.2 API). Unknown or odd arguments are ignored, not fatal. Vectors are `[x, y, z]` in metres (Blender units); rotations are in degrees
(`rotation_deg`). Objects are referred to by the `name` they were given.

Example:

```json
{"calls":[
  {"tool":"add_primitive","shape":"cube","name":"Box","location":[0,0,1]},
  {"tool":"set_material","object":"Box","name":"Red","color":[0.8,0.1,0.1]},
  {"tool":"add_light","kind":"SUN","location":[4,-4,6],"energy":3},
  {"tool":"add_camera","location":[6,-6,4],"rotation_deg":[63,0,45]}
]}
```

There are %d tools in the executor. %s Types: `number`, `integer`, `string`, `boolean`, `vec3` = array of 3 numbers, `[...]` = array.

"""


def typ(p):
    if "const" in p:
        return repr(p["const"])
    if "enum" in p:
        return " \\| ".join(str(x) for x in p["enum"])
    t = p.get("type")
    if t == "array":
        it = p.get("items", {})
        if it.get("type") == "number" and p.get("minItems") == 3 and p.get("maxItems") == 3:
            return "vec3"
        return "[%s]" % typ(it)
    return str(t)


def render():
    manifest = json.load(open(os.path.join(ROOT, "src", "maris3d", "copilot", "data", "TOOLS.json")))
    names = [t["properties"]["tool"]["const"] for t in T.TOOLS]
    extra = [n for n in names if n not in manifest]
    note = "The app's compiler writes calls with the %d in `TOOLS.json`" % len(manifest)
    if extra:
        note += "; %s %s run only from code (the scene harness), never from a model answer or the compiler" % (
            " and ".join("`%s`" % n for n in extra), "is" if len(extra) == 1 else "are")
    out = [HEAD % (T.SCHEMA["properties"]["calls"]["maxItems"], len(T.TOOLS), note + ".")]
    for t in T.TOOLS:
        props, req = t["properties"], set(t.get("required", []))
        name = props["tool"]["const"]
        out.append("## `%s`\n" % name)
        out.append("| argument | type | required |\n|---|---|---|")
        for k, v in props.items():
            if k != "tool":
                out.append("| `%s` | %s | %s |" % (k, typ(v), "yes" if k in req else ""))
        out.append("")
    return "\n".join(out)


if __name__ == "__main__":
    text = render()
    p = os.path.join(ROOT, "docs", "DSL.md")
    if "--check" in sys.argv:
        sys.exit(0 if os.path.exists(p) and open(p).read() == text else 1)
    open(p, "w").write(text)
    print("wrote docs/DSL.md (%d tools)" % len(T.TOOLS))
